// Checks that every Markdown file in the repository keeps its lines within
// the maximum length and pads its tables so the columns line up. Run with
// --fix to pad the tables in place. Long lines have to be wrapped by hand.
//
// Fenced code blocks and tables are exempt from the line length, and so is a
// line that only runs over because of a single unbreakable word, such as a
// URL. Changelogs are generated by the release tooling and are not checked.

import 'dart:io';

import 'src/markdown_tables.dart';

const maximumLineLength = 100;

void main(List<String> arguments) {
  final fix = arguments.contains('--fix');
  final repositoryRoot = File.fromUri(Platform.script).parent.parent;
  Directory.current = repositoryRoot.path;

  final files = Process.runSync('git', [
    'ls-files',
    '--cached',
    '--others',
    '--exclude-standard',
    '*.md',
    '*.md.tmpl',
  ]).stdout.toString().split('\n').where(_isChecked);

  final unformatted = <String>[];
  final longLines = <String>[];
  for (final path in files) {
    final file = File(path);
    final content = file.readAsStringSync();
    final formatted = formatTables(content);
    if (formatted != content) {
      unformatted.add(path);
      if (fix) file.writeAsStringSync(formatted);
    }
    longLines.addAll(_longLines(path, formatted));
  }

  if (unformatted.isNotEmpty) {
    if (fix) {
      stdout
        ..writeln('Padded the tables in:')
        ..writeAll(unformatted.map((path) => '  $path\n'));
    } else {
      stderr
        ..writeln('Tables are not padded in:')
        ..writeAll(unformatted.map((path) => '  $path\n'))
        ..writeln('Run `dart scripts/check_markdown.dart --fix` to pad them.');
      exitCode = 1;
    }
  }
  if (longLines.isNotEmpty) {
    stderr
      ..writeln('Lines longer than $maximumLineLength characters:')
      ..writeAll(longLines.map((line) => '  $line\n'))
      ..writeln('Wrap them by hand.');
    exitCode = 1;
  }
  if (exitCode == 0) stdout.writeln('Markdown files are formatted.');
}

bool _isChecked(String path) =>
    path.isNotEmpty &&
    !path.endsWith('CHANGELOG.md') &&
    !FileSystemEntity.isLinkSync(path);

Iterable<String> _longLines(String path, String content) sync* {
  var inCode = false;
  for (final (index, line) in content.split('\n').indexed) {
    if (line.trimLeft().startsWith('```')) {
      inCode = !inCode;
      continue;
    }
    if (inCode || line.trimLeft().startsWith('|')) continue;
    final length = line.runes.length;
    if (length <= maximumLineLength) continue;
    final overflow = String.fromCharCodes(line.runes.skip(maximumLineLength));
    if (!overflow.contains(' ')) continue;
    yield '$path:${index + 1} ($length characters)';
  }
}
